def balanced(s: str) -> bool:
    stack = []
    brackets = {"(": ")", "[": "]", "{": "}"}

    for char in s:
        if char in brackets:
            stack.append(brackets[char])
        elif stack and stack[-1] == char:
            stack.pop()
        elif not stack:
            return False

    return len(stack) == 0
