def caesar(s: str, k: int) -> str:
    result = []
    for char in s:
        if char.isalpha():
            # Shift the character by k positions
            shifted = ord(char) + k
            # Wrap around if needed
            if shifted > ord('Z'):
                shifted -= 26
            elif shifted < ord('A'):
                shifted += 26
            result.append(chr(shifted))
        else:
            result.append(char)
    return ''.join(result)
