def group_anagrams(words: list) -> list:
    from collections import defaultdict

    groups = defaultdict(list)
    first_appearance = {}

    for word in words:
        if word in first_appearance:
            groups[first_appearance[word]].append(word)
        else:
            first_appearance[word] = len(groups)
            groups[len(groups)].append(word)

    result = []
    for group in groups.values():
        result.append(group)

    return result
