def eval_rpn(tokens: list) -> int:
    stack = []
    for token in tokens:
        if token == "/":
            if stack:
                divisor = stack.pop()
                quotient = divisor / stack[-1]
                stack.append(quotient)
            else:
                stack.append(0)
        elif token == "+":
            if stack and len(stack) >= 2:
                a = stack.pop()
                b = stack.pop()
                stack.append(a + b)
            elif stack:
                stack.append(0)
        elif token == "-":
            if stack and len(stack) >= 2:
                a = stack.pop()
                b = stack.pop()
                stack.append(b - a)
            elif stack:
                stack.append(0)
        elif token == "*":
            if stack and len(stack) >= 2:
                a = stack.pop()
                b = stack.pop()
                stack.append(a * b)
            elif stack:
                stack.append(0)
        elif token == "/":
            if stack and len(stack) >= 2:
                a = stack.pop()
                b = stack.pop()
                stack.append(b // a)
            elif stack:
                stack.append(0)
    return stack[0]
```

