def longest_unique_substring(s: str) -> int:
    start = 0
    max_len = 0
    seen = set()
    for end in range(len(s)):
        if s[end] in seen:
            while s[start] != s[end]:
                seen.remove(s[start])
                start += 1
        else:
            seen.add(s[end])
        max_len = max(max_len, end - start + 1)
    return max_len
