def binary_search_first(a: list, x) -> int:
    low = 0
    high = len(a) - 1
    while low <= high:
        mid = (low + high) // 2
        if a[mid] == x:
            # Check if it's the first occurrence
            result = mid
            high = mid - 1
        elif a[mid] > x:
            high = mid - 1
        else:
            low = mid + 1
    return result if result != len(a) else -1
