def lru_simulate(capacity: int, ops: list) -> list:
    cache = {}
    recent = []
    result = []

    for op in ops:
        if op[0] == 'put':
            if len(recent) < capacity:
                recent.append(op[1])
            else:
                removed = recent.pop(0)
                cache.pop(removed)
            recent.append(op[1])
            cache[op[1]] = True
        elif op[0] == 'get':
            if op[1] in cache:
                result.append(cache[op[1]])
                recent.append(op[1])
            else:
                result.append(-1)
    return result
```

