from collections import defaultdict

def topo_sort(n: int, edges: list) -> list:
    graph = defaultdict(list)
    in_degree = [0] * n
    order = []

    for u, v in edges:
        graph[u].append(v)
        in_degree[v] += 1

    # Initialize queue with nodes having in_degree 0
    queue = []
    for i in range(n):
        if in_degree[i] == 0:
            queue.append(i)

    while queue:
        u = queue.pop(0)
        order.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(order) != n:
        return None
    else:
        return order
```

