def decode_string(s: str) -> str:
    stack = []
    current = ""

    for char in s:
        if char.isdigit():
            current += char
        elif char == '[':
            stack.append(current)
            current = ""
        elif char == ']":
            # Pop the last value and combine with the current
            last = stack.pop()
            current = last + current
        else:
            current += char

    return current
```

