def moving_average(values: list, window: int) -> list:
    if window < 1:
        raise ValueError
    if len(values) < window:
        return []
    result = []
    for i in range(len(values)):
        if i >= window - 1:
            result.append(sum(values[i - window + 1 : i + 1]) / window)
    return result
```

